export type IconName = keyof typeof ICONS;

export interface AppIconComponentProps {
  size?: number;
  className?: string;
  'aria-label'?: string;
}

/** Render any delivered icon by name: <AppIcon name="nav-chat" size={20} /> */
export function AppIcon({
  name,
  size = 24,
  className,
  'aria-label': ariaLabel,
}: { name: IconName } & AppIconComponentProps) {
  const Cmp = ICONS[name] as ComponentType<AppIconComponentProps & { size?: number }>;
  return <Cmp size={size} className={className} aria-label={ariaLabel} />;
}
